// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"market-capitalization":{"slug":"market-capitalization","cat":"basics","en":"Market capitalization","contentLocale":"pt-BR","term":"Capitalização de mercado (market cap)","aka":["market cap","valor de mercado"],"short":"Capitalização de mercado é o valor total de uma criptomoeda, calculado multiplicando o preço atual pela oferta circulante de moedas.","body":[["A fórmula é simples: preço vezes ",["oferta circulante","circulating-supply"],". Se uma moeda vale 2 dólares e há 500 milhões de unidades em circulação, a capitalização é de 1 bilhão de dólares. Sites de dados de mercado usam esse número para montar os rankings de criptomoedas."],"O market cap ajuda a comparar projetos de forma justa. Uma moeda de 0,01 dólar pode valer mais no total do que outra de 100 dólares, se tiver muito mais unidades. Olhar só o preço unitário engana.",["Mas o número tem limites. Ele depende de quanta oferta é considerada circulante, e projetos com muitos tokens ainda travados podem parecer menores do que serão. Também não diz quanto dinheiro realmente entrou no ativo nem quanto daria para vender sem derrubar o preço. Por isso vale olhar junto o ",["FDV","fully-diluted-valuation"]," e o volume negociado."]],"example":"Imagine duas moedas. A moeda A custa US$ 0,05 e tem 40 bilhões de unidades circulando: market cap de US$ 2 bilhões. A moeda B custa US$ 20 e tem 50 milhões em circulação: market cap de US$ 1 bilhão. Apesar do preço unitário menor, A vale o dobro de B no mercado. Para A chegar a US$ 1 por unidade, seu market cap teria de ir a US$ 40 bilhões.","mistakes":["Comparar moedas pelo preço unitário em vez do market cap.","Ignorar que tokens ainda bloqueados vão entrar em circulação e diluir o valor por unidade.","Achar que market cap alto significa que o ativo é seguro ou que não pode cair muito."],"faq":[{"q":"Como calcular o market cap de uma cripto?","a":"Multiplique o preço atual pela oferta circulante. Os sites de dados fazem esse cálculo automaticamente, mas podem divergir conforme a fonte da oferta circulante."},{"q":"Market cap baixo é bom?","a":"Moedas de market cap baixo podem se mover mais em porcentagem, para cima e para baixo. Elas costumam ter menos liquidez e mais risco de manipulação."}],"title":"O que é capitalização de mercado (market cap) em cripto?","description":"Aprenda o que é market cap, como calcular preço vezes oferta circulante e por que comparar só o preço unitário engana.","related":[["fully-diluted-valuation","Valor totalmente diluído (FDV)","FDV (valor totalmente diluído) é o valor que uma criptomoeda teria se toda a sua oferta máxima já estivesse em circulação, calculado como preço vezes oferta máxima ou total."],["circulating-supply","Oferta circulante","Oferta circulante é a quantidade de unidades de uma criptomoeda que já está disponível e pode ser negociada no mercado, sem contar tokens bloqueados ou ainda não emitidos."],["trading-volume","Volume de negociação","Volume de negociação é a quantidade total de um ativo comprada e vendida em um período, geralmente as últimas 24 horas, medida em moedas ou em dólares."],["tokenomics","Tokenomics","Tokenomics é o conjunto de regras econômicas de um token: oferta total, distribuição entre equipe e investidores, cronograma de liberação, utilidade e mecanismos como queima ou recompensas."],["altcoin","Altcoin","Altcoin é qualquer criptomoeda que não seja o bitcoin, de grandes redes como Ethereum e Solana até tokens pequenos e memecoins."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"market-maker":{"slug":"market-maker","cat":"trading","en":"Market maker","contentLocale":"pt-BR","term":"Formador de mercado (market maker)","aka":["market maker","formador de mercado","MM"],"short":"Um formador de mercado (market maker) é uma empresa ou trader que mantém ordens de compra e venda no livro o tempo todo, oferecendo liquidez e lucrando principalmente com o spread.","body":["O market maker coloca uma ordem de compra um pouco abaixo do preço e uma de venda um pouco acima. Quando os dois lados são executados, ele ganha a diferença. Para isso, usa algoritmos que ajustam as ordens em milissegundos conforme o mercado se move e controla o risco de ficar com estoque demais de um lado.",["Sem formadores de mercado, os livros seriam rasos, os spreads largos e o ",["slippage","slippage"]," alto. Por isso corretoras costumam oferecer taxas maker menores ou até rebates para quem fornece ",["liquidez","liquidity"]," de forma constante. Projetos de tokens também contratam market makers para garantir liquidez no lançamento."],["No ",["DeFi","defi"],", o papel de market maker é feito por um ",["AMM","amm"]," (formador de mercado automatizado): em vez de ordens no livro, a liquidez fica em um pool e uma fórmula define o preço. Quem deposita no pool atua como formador de mercado e recebe parte das taxas."]],"example":["Suponha que ",["ETH","ethereum"]," esteja em 3.000 ",["USDT","usdt"],". Um market maker coloca compra a 2.999 e venda a 3.001, 5 ETH de cada lado. Se as duas ordens forem executadas, ele compra por 14.995 USDT e vende por 15.005 USDT, ganhando 10 USDT antes das taxas. Se em vez disso o preço cair para 2.950 depois da compra, ele fica com 5 ETH desvalorizados, por isso precisa gerenciar o estoque com cuidado."],"mistakes":["Achar que todo market maker manipula o preço, quando a função principal é fornecer liquidez.","Supor que um token recém-lançado sempre terá liquidez, sem saber se há formador de mercado ativo.","Confundir ser maker em uma ordem isolada com atuar como formador de mercado profissional."],"faq":[{"q":"Como um market maker ganha dinheiro?","a":"Principalmente com o spread entre compra e venda e com rebates ou taxas reduzidas oferecidos pelas corretoras. O risco dele é ficar com estoque quando o preço se move forte."},{"q":"Qualquer pessoa pode ser market maker?","a":"Qualquer um pode colocar ordens limitadas no livro, mas atuar como formador de mercado profissional exige capital, tecnologia e controle de risco. Em pools de liquidez DeFi, qualquer pessoa pode fornecer liquidez."}],"title":"O que é market maker (formador de mercado) em cripto?","description":"Entenda o que faz um market maker, como ele lucra com o spread e por que formadores de mercado deixam o livro de ofertas mais líquido.","related":[["liquidity","Liquidez","Liquidez é a facilidade de comprar ou vender um ativo rapidamente, em quantidade relevante, sem mexer muito no preço."],["bid-ask-spread","Spread (diferença entre compra e venda)","Spread é a diferença entre o melhor preço de compra (bid) e o melhor preço de venda (ask) no livro de ofertas de um par, e funciona como um custo implícito de operar."],["maker-taker-fees","Taxas maker e taker","Taxas maker e taker são as duas tarifas que uma corretora cobra por negociação: a maker vale para ordens que ficam no livro de ofertas e adicionam liquidez, e a taker para ordens que executam na hora e retiram liquidez."],["order-book","Livro de ofertas (order book)","Livro de ofertas (order book) é a lista em tempo real de todas as ordens limitadas de compra e de venda de um par, organizadas por preço, que mostra a profundidade do mercado."],["amm","Formador de mercado automatizado (AMM)","Um formador de mercado automatizado (AMM) é um contrato inteligente que define o preço de uma troca por uma fórmula matemática aplicada às reservas de um pool de liquidez, em vez de casar ordens de compradores e vendedores."]],"lesson":null,"coin":null,"tool":null,"cta":false},"risk-reward-ratio":{"slug":"risk-reward-ratio","cat":"trading","en":"Risk-reward ratio","contentLocale":"pt-BR","term":"Relação risco-retorno","aka":["risco/retorno","risk-reward","R:R","relação risco/recompensa"],"short":"Relação risco-retorno é a comparação entre quanto você pode perder até o stop loss e quanto pode ganhar até o alvo de uma operação, como 1 para 3.","body":[["Para calcular, meça a distância da entrada até o stop (risco) e da entrada até o ",["take profit","take-profit"]," (retorno). Se você arrisca 100 para tentar ganhar 300, a relação é de 1 para 3. Muitos traders escrevem isso como 1:3 ou dizem que o alvo vale 3R."],"A relação só faz sentido junto com a taxa de acerto. Com 1 para 3, você pode errar a maioria das operações e ainda terminar no lucro. Com 1 para 1, precisa acertar mais da metade, já descontando taxas. Por isso não existe uma relação \"certa\": alvos muito distantes têm menos chance de serem atingidos.",["Defina stop e alvo com base no gráfico, por exemplo em zonas de ",["suporte e resistência","support-and-resistance"],", e não em números inventados para fazer a conta parecer boa. Ordens ",["OCO","oco-order"]," permitem deixar stop e alvo prontos ao mesmo tempo."]],"example":["Suponha que você compre uma moeda a 2,00 ",["USDT","usdt"],", com stop em 1,90 e alvo em 2,30. O risco é 0,10 e o retorno é 0,30, uma relação de 1 para 3. Em 10 operações iguais, se você acertar só 4 e errar 6, ganha 4 vezes 0,30 (1,20) e perde 6 vezes 0,10 (0,60) por moeda. O saldo é positivo de 0,60 por moeda, antes das taxas."],"mistakes":["Mover o stop para longe depois de entrar, o que piora a relação que você planejou.","Escolher alvos irreais só para a conta mostrar uma relação alta.","Ignorar a taxa de acerto e achar que uma boa relação risco-retorno basta."],"faq":[{"q":"Qual é uma boa relação risco-retorno?","a":"Muitos traders buscam pelo menos 1 para 2, mas o ideal depende da sua taxa de acerto. O que importa é que a combinação dos dois seja positiva depois das taxas."},{"q":"Como calcular o risco-retorno de uma operação?","a":"Divida a distância entre a entrada e o alvo pela distância entre a entrada e o stop. Se o alvo está 15 acima e o stop 5 abaixo, a relação é de 1 para 3."}],"title":"O que é relação risco-retorno? Como calcular","description":"Entenda a relação risco-retorno no trading de cripto, como calculá-la com stop e alvo e por que ela depende da taxa de acerto.","related":[["position-sizing","Dimensionamento de posição","Dimensionamento de posição (position sizing) é decidir quanto colocar em cada operação com base em quanto você aceita perder se o stop loss for atingido."],["stop-loss","Stop loss","Stop loss é uma ordem programada para vender, ou fechar uma posição, automaticamente quando o preço atinge um nível definido, limitando a perda de uma operação."],["take-profit","Take profit","Take profit é uma ordem programada para fechar uma posição automaticamente quando o preço atinge um alvo de lucro definido por você."],["oco-order","Ordem OCO (uma cancela a outra)","Ordem OCO (one-cancels-the-other) é um par de ordens ligadas, normalmente um take profit e um stop loss, em que a execução de uma cancela automaticamente a outra."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Decida quanto você pode perder antes de decidir quanto comprar"},"coin":null,"tool":null,"cta":false},"futures-contract":{"slug":"futures-contract","cat":"derivatives","en":"Futures contract","contentLocale":"pt-BR","term":"Contrato futuro","aka":["futuros","mercado futuro","futures"],"short":"Um contrato futuro é um acordo para comprar ou vender um ativo a um preço definido, com liquidação em uma data futura ou, no caso dos perpétuos, sem data de vencimento.","body":[["No cripto, você não recebe a moeda ao operar futuros. Você negocia um contrato que acompanha o preço dela. Isso permite apostar na alta (posição comprada, ou long) ou na queda (posição vendida, ou short) e usar ",["alavancagem","leverage"],", depositando só uma parte do valor como margem."],["Há dois tipos principais. Os ",["futuros com vencimento","delivery-futures"]," (trimestrais, por exemplo) encerram em uma data fixa e são liquidados pelo preço de referência daquele momento. Os ",["futuros perpétuos","perpetual-futures"]," não vencem e usam uma ",["taxa de financiamento","funding-rate"]," para manter o preço próximo do ",["mercado à vista","spot-trading"],". Também há diferença na moeda da margem: contratos ",["lineares","usdt-margined-futures"]," usam USDT ou USDC, e contratos inversos usam a própria moeda, como BTC."],"Além da especulação, futuros servem para proteção (hedge). Quem tem BTC guardado pode abrir um short para reduzir o efeito de uma queda. Cada corretora tem regras próprias de margem, alavancagem máxima e liquidação, publicadas na especificação do contrato."],"example":"Suponha que BTC esteja a 60.000 USDT e você abra um long de 0,1 BTC, valor nocional de 6.000 USDT, com alavancagem de 5x. Você deposita 1.200 USDT de margem. Se o preço subir para 63.000, o ganho é 0,1 vezes 3.000, ou 300 USDT, 25% sobre a margem. Se cair para 57.000, a perda é de 300 USDT, também 25% da margem, antes de taxas e financiamento.","mistakes":["Achar que operar futuros é o mesmo que ter a moeda, quando você só tem um contrato e não pode sacar o ativo.","Calcular ganho e perda sobre a margem sem perceber que a alavancagem multiplica os dois.","Ignorar taxas de financiamento e taxas de negociação, que pesam em posições mantidas por muito tempo."],"faq":[{"q":"Qual a diferença entre futuros e spot?","a":"No spot você compra e passa a ter a moeda. Nos futuros você negocia um contrato sobre o preço, pode operar vendido e usar alavancagem, mas corre risco de liquidação."},{"q":"Contratos futuros de cripto vencem?","a":"Os futuros com data de entrega vencem em datas fixas, como no fim de cada trimestre. Os perpétuos não vencem e ficam abertos até você fechar ou ser liquidado."}],"title":"O que é contrato futuro em cripto? Como funciona","description":"Entenda o que são contratos futuros de cripto, a diferença entre perpétuos e com vencimento, margem, long, short e alavancagem.","related":[["perpetual-futures","Futuros perpétuos","Futuros perpétuos são contratos futuros sem data de vencimento, que acompanham o preço à vista do ativo por meio de uma taxa de financiamento paga periodicamente entre comprados e vendidos."],["delivery-futures","Futuros com vencimento (trimestrais)","Futuros com vencimento (ou de entrega) são contratos que encerram em uma data fixa, como no fim de um trimestre, e são liquidados pelo preço de referência do ativo nesse momento."],["leverage","Alavancagem","Alavancagem é o uso de margem para abrir uma posição maior do que o seu capital, multiplicando tanto os ganhos quanto as perdas em relação ao valor depositado."],["margin-trading","Negociação com margem","Negociação com margem é operar usando dinheiro ou moedas emprestadas pela corretora, com o seu saldo como garantia, para abrir posições maiores ou vender a descoberto."],["hedging","Hedge (proteção)","Hedge é abrir uma posição que ganha quando a sua posição principal perde, para reduzir o impacto de movimentos de preço contra você, em troca de abrir mão de parte do ganho."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futuros: você não está comprando a mesma coisa"},"coin":null,"tool":"/topics/derivatives","cta":true},"cross-margin":{"slug":"cross-margin","cat":"derivatives","en":"Cross margin","contentLocale":"pt-BR","term":"Margem cruzada","aka":["cross margin","modo cruzado","cruzada"],"short":"Margem cruzada é o modo em que todo o saldo disponível da conta de futuros serve de garantia para as posições abertas, afastando a liquidação mas colocando o saldo inteiro em risco.","body":["No modo cruzado, a margem não fica presa a uma posição. Se uma operação está perdendo, ela puxa saldo livre da conta para não ser liquidada. Ganhos não realizados de outras posições também podem ajudar a sustentar a que está no prejuízo.",["Isso torna a ",["liquidação","liquidation"]," mais distante e é útil para estratégias com posições que se compensam, como um long em uma moeda e um short em outra. O lado ruim é que, se o mercado se mover forte contra você, a liquidação pode levar todo o saldo da conta, e não apenas a margem de uma operação."],"Em contas unificadas, oferecidas por corretoras como OKX, Bybit e Binance, a margem cruzada pode incluir saldos de várias moedas, com descontos de valor para ativos mais voláteis. As regras de cálculo variam, então vale ler a explicação de margem da sua conta."],"example":["Você tem 4.000 ",["USDT","usdt"]," na conta e abre um long de ",["BTC","bitcoin"]," de 20.000 USDT de valor nocional em margem cruzada. A corretora mostra uma ",["alavancagem","leverage"]," de 5x sobre o saldo. Como todo o saldo protege a posição, a liquidação só ocorre com uma queda próxima de 19,5%, considerando manutenção de 0,5%. Mas, se essa queda acontecer, você perde quase os 4.000 USDT, e não só uma parte."],"mistakes":["Deixar saldo grande na conta de futuros em modo cruzado sem perceber que todo ele está em risco.","Abrir várias posições na mesma direção achando que a margem cruzada diversifica o risco.","Esquecer que transferir saldo para fora da conta aproxima a liquidação das posições abertas."],"faq":[{"q":"Margem cruzada é mais segura?","a":"Ela afasta a liquidação de cada posição, mas aumenta a perda máxima, porque todo o saldo pode ser consumido. Segurança depende do tamanho da posição e do stop."},{"q":"Como saber se estou em margem cruzada?","a":"A tela de negociação de futuros mostra o modo, geralmente como Cruzada ou Isolada, ao lado da alavancagem. Você pode trocar quando não houver posição aberta no contrato."}],"title":"O que é margem cruzada em cripto? Como funciona","description":"Entenda como funciona a margem cruzada em futuros cripto, por que ela afasta a liquidação e por que coloca todo o saldo em risco.","related":[["isolated-margin","Margem isolada","Margem isolada é o modo em que cada posição tem sua própria margem separada, de modo que uma liquidação só consome o valor alocado àquela posição e não o resto da conta."],["portfolio-margin","Margem de portfólio","Margem de portfólio é um modo de cálculo em que a exigência de margem considera o risco líquido de todas as posições juntas, permitindo menos margem quando elas se compensam."],["unified-trading-account","Conta unificada de negociação (UTA)","Uma conta unificada de negociação é um modelo de conta em que spot, margem, futuros e opções compartilham o mesmo saldo e a mesma margem, sem precisar transferir fundos entre carteiras separadas."],["liquidation","Liquidação","Liquidação é o fechamento forçado de uma posição alavancada pela corretora quando a margem restante cai abaixo da margem de manutenção, para evitar que as perdas ultrapassem a garantia."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Margem cruzada: por que uma perda pode atingir suas outras posições"},"coin":null,"tool":null,"cta":false},"long-and-short":{"slug":"long-and-short","cat":"derivatives","en":"Long and short positions","contentLocale":"pt-BR","term":"Posição comprada e vendida (long e short)","aka":["long","short","comprado","vendido"],"short":"Long e short são as duas direções de uma operação: long (comprado) lucra quando o preço sobe, e short (vendido) lucra quando o preço cai.","body":[["No ",["mercado à vista","spot-trading"],", ficar comprado é simples: você compra a moeda e espera a valorização. Ficar vendido exige vender algo que você não tem, o que é possível na ",["margem spot","margin-trading"],", pegando a moeda emprestada, ou nos futuros, abrindo uma posição vendida no contrato."],["Nos ",["futuros perpétuos","perpetual-futures"],", abrir long ou short é igualmente fácil: é só escolher o botão comprar/long ou vender/short. A diferença está no risco. Em um long sem ",["alavancagem","leverage"],", a perda máxima é o valor investido, porque o preço não cai abaixo de zero. Em um short, o preço pode subir sem limite teórico, então a perda potencial é maior e a ",["liquidação","liquidation"]," protege a corretora."],["Algumas corretoras permitem o modo ",["hedge","hedging"],", em que você mantém long e short no mesmo contrato ao mesmo tempo. No modo de posição única, uma ordem de venda reduz ou inverte o seu long."]],"example":"Suponha que XRP esteja a 0,60 USDT. Você abre um long de 5.000 XRP e um amigo abre um short de 5.000 XRP. Se o preço subir para 0,66, você ganha 5.000 vezes 0,06, ou 300 USDT, e ele perde 300 USDT. Se cair para 0,54, a situação se inverte. Em cada caso, taxas e funding são descontados do resultado.","mistakes":["Achar que short é proibido ou exótico, quando é uma operação comum em futuros.","Esquecer que no modo de posição única uma venda grande pode inverter o long em short.","Subestimar o risco de um short em moedas pequenas sujeitas a altas bruscas."],"faq":[{"q":"O que significa estar long?","a":"Significa estar comprado, com uma posição que ganha se o preço subir. É o contrário de estar short, ou vendido."},{"q":"É possível ficar short no spot?","a":"No spot comum não, porque você precisa ter a moeda para vender. Para ficar vendido é preciso usar margem spot ou futuros."}],"title":"O que é long e short em cripto? Comprado e vendido","description":"Entenda a diferença entre posição long (comprada) e short (vendida) em cripto, como lucrar em cada direção e os riscos de cada uma.","related":[["short-selling","Venda a descoberto (short selling)","Venda a descoberto (short selling) é vender um ativo que você não possui, por empréstimo ou por contrato futuro, para recomprá-lo depois mais barato e lucrar com a queda do preço."],["perpetual-futures","Futuros perpétuos","Futuros perpétuos são contratos futuros sem data de vencimento, que acompanham o preço à vista do ativo por meio de uma taxa de financiamento paga periodicamente entre comprados e vendidos."],["leverage","Alavancagem","Alavancagem é o uso de margem para abrir uma posição maior do que o seu capital, multiplicando tanto os ganhos quanto as perdas em relação ao valor depositado."],["long-short-ratio","Relação long/short","Relação long/short é um indicador que compara quantas contas ou quanto volume de posições estão comprados versus vendidos em um contrato futuro, mostrando o posicionamento dos traders."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futuros: você não está comprando a mesma coisa"},"coin":null,"tool":null,"cta":true},"short-selling":{"slug":"short-selling","cat":"derivatives","en":"Short selling","contentLocale":"pt-BR","term":"Venda a descoberto (short selling)","aka":["short selling","vender a descoberto","shortar","operar vendido"],"short":"Venda a descoberto (short selling) é vender um ativo que você não possui, por empréstimo ou por contrato futuro, para recomprá-lo depois mais barato e lucrar com a queda do preço.","body":[["Na ",["margem spot","margin-trading"],", o processo é literal: você pega emprestado, por exemplo, 1 ",["ETH","ethereum"],", vende pelo ",["preço atual","last-price"],", espera a queda, recompra e devolve o ETH, pagando juros pelo empréstimo. Nos futuros, não há empréstimo explícito: você abre uma posição vendida no contrato e o lucro ou perda é calculado pela diferença de preço."],["O risco do short é assimétrico. O preço pode cair no máximo até zero, então o ganho é limitado, mas pode subir muito, e a perda cresce sem um teto teórico. Em mercados com muito short aberto, uma alta rápida pode forçar recompra em massa e virar um ",["short squeeze","short-squeeze"],"."],"Além do risco de preço, há custos: juros na margem spot ou funding nos perpétuos. Quando o funding está muito negativo, quem está vendido paga a taxa periodicamente, o que reduz o resultado de posições mantidas por muito tempo."],"example":["Você pega 10 SOL emprestados na margem spot e vende a 160 ",["USDT","usdt"],", recebendo 1.600 USDT. Uma semana depois, SOL cai para 140, e você recompra os 10 SOL por 1.400 USDT e devolve. O lucro bruto é de 200 USDT. Se os juros do empréstimo somarem 3 USDT na semana, o resultado fica em 197 USDT antes das taxas de negociação."],"mistakes":["Abrir short sem stop loss, contando que o preço sempre volta a cair.","Ignorar o custo de juros ou funding em shorts mantidos por muito tempo.","Vender a descoberto moedas de baixa liquidez muito populares em redes sociais, mais sujeitas a squeezes."],"faq":[{"q":"Como ficar vendido em cripto?","a":"Você pode abrir um short em futuros, inclusive perpétuos, ou pegar a moeda emprestada na margem spot e vendê-la. Os dois exigem margem e têm risco de liquidação."},{"q":"Quanto posso perder em um short?","a":"Em teoria, a perda não tem limite, porque o preço pode subir indefinidamente. Na prática, a liquidação fecha a posição antes, levando a margem."}],"title":"O que é venda a descoberto (short) em cripto?","description":"Entenda como funciona a venda a descoberto em cripto pela margem ou por futuros, os custos envolvidos e o risco de perda ilimitada.","related":[["long-and-short","Posição comprada e vendida (long e short)","Long e short são as duas direções de uma operação: long (comprado) lucra quando o preço sobe, e short (vendido) lucra quando o preço cai."],["perpetual-futures","Futuros perpétuos","Futuros perpétuos são contratos futuros sem data de vencimento, que acompanham o preço à vista do ativo por meio de uma taxa de financiamento paga periodicamente entre comprados e vendidos."],["margin-trading","Negociação com margem","Negociação com margem é operar usando dinheiro ou moedas emprestadas pela corretora, com o seu saldo como garantia, para abrir posições maiores ou vender a descoberto."],["short-squeeze","Short squeeze","Short squeeze é uma alta rápida de preço provocada pela recompra forçada de quem estava vendido, seja por stop loss ou liquidação, o que empurra o preço ainda mais para cima."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futuros: você não está comprando a mesma coisa"},"coin":null,"tool":null,"cta":false},"futures-basis":{"slug":"futures-basis","cat":"derivatives","en":"Futures basis","contentLocale":"pt-BR","term":"Base de futuros","aka":["basis","base","prêmio de futuros","futures basis"],"short":"Base de futuros é a diferença entre o preço de um contrato futuro e o preço à vista do mesmo ativo, normalmente expressa em valor ou em porcentagem anualizada.","body":[["Quando o futuro negocia acima do spot, a base é positiva, situação chamada contango, comum em mercados otimistas. Quando negocia abaixo, a base é negativa, chamada backwardation. Nos ",["futuros com vencimento","delivery-futures"],", a base tende a diminuir com o tempo e chega a zero no vencimento, quando o contrato é ",["liquidado","liquidation"]," pelo índice."],"Para comparar contratos de prazos diferentes, traders anualizam a base. Uma base de 2% com 60 dias até o vencimento equivale a cerca de 12% ao ano. Esse número é o retorno teórico da operação cash and carry: comprar no spot e vender o futuro, travando a diferença.",["Nos perpétuos, a base é pequena e oscila, e o papel de alinhar os preços fica com a ",["taxa de financiamento","funding-rate"],". Base alta e crescente costuma refletir demanda forte por posições compradas alavancadas."]],"example":["Suponha ",["BTC","bitcoin"]," a 60.000 ",["USDT","usdt"]," no spot e o futuro de 120 dias a 62.400. A base é de 2.400 USDT, ou 4%. Anualizando, 4% vezes 365 dividido por 120 dá cerca de 12,2% ao ano. Comprando 1 BTC no spot e vendendo 1 BTC no futuro, você trava cerca de 2.400 USDT até o vencimento, descontadas taxas e o custo de manter a margem."],"mistakes":["Comparar bases de contratos com prazos diferentes sem anualizar.","Achar que a operação de base não tem risco, ignorando liquidação da perna vendida e risco da corretora.","Confundir base com taxa de financiamento."],"faq":[{"q":"O que significa base positiva?","a":"Que o futuro está mais caro que o spot, situação chamada contango. Indica que há demanda por posições compradas em futuros."},{"q":"Como ganhar com a base?","a":"Com a operação cash and carry: comprar o ativo no spot e vender o futuro, recebendo a diferença quando os preços convergem no vencimento."}],"title":"O que é base de futuros? Contango e backwardation","description":"Entenda o que é a base de futuros em cripto, como anualizar a diferença para o spot e como funciona a operação cash and carry.","related":[["delivery-futures","Futuros com vencimento (trimestrais)","Futuros com vencimento (ou de entrega) são contratos que encerram em uma data fixa, como no fim de um trimestre, e são liquidados pelo preço de referência do ativo nesse momento."],["funding-rate","Taxa de financiamento (funding rate)","Taxa de financiamento (funding rate) é um pagamento periódico entre traders comprados e vendidos em futuros perpétuos, usado para manter o preço do contrato próximo do preço à vista."],["index-price","Preço índice","Preço índice é a média ponderada do preço à vista de um ativo em várias corretoras, usada como referência para o preço de marcação e a taxa de financiamento."],["funding-rate-arbitrage","Arbitragem de taxa de financiamento","Arbitragem de taxa de financiamento é a estratégia de comprar um ativo no spot e abrir um short do mesmo tamanho no perpétuo, ficando neutro ao preço e recebendo o funding quando ele é positivo."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"blockchain-network":{"slug":"blockchain-network","cat":"wallets-security","en":"Deposit network (chain selection)","contentLocale":"pt-BR","term":"Rede de depósito (escolha da rede)","aka":["rede blockchain","rede de saque","network","escolha da rede"],"short":"A rede de depósito é a blockchain específica, como Ethereum (ERC20), Tron (TRC20) ou Solana, pela qual uma criptomoeda é transferida, e precisa ser a mesma no envio e no recebimento para o dinheiro chegar.","body":[["Muitos ativos existem em várias redes ao mesmo tempo. O ",["USDT","usdt"],", por exemplo, circula em ",["Ethereum","ethereum"],", Tron, Solana, BNB Smart Chain e outras. Na tela de saque da corretora você escolhe a moeda e depois a rede. Cada rede tem taxa, tempo de confirmação e formato de endereço próprios."],"Se a origem envia por uma rede e o destino não suporta essa rede, o depósito pode não ser creditado. Às vezes a corretora consegue recuperar, cobrando uma taxa e levando dias. Às vezes não há recuperação possível, principalmente se o destino é uma carteira que não controla aquele endereço na outra rede.","Antes de sacar, abra a página de depósito do destino, veja quais redes ele aceita para aquele ativo e escolha uma em comum. A rede mais barata não serve de nada se o destino não aceita."],"example":"Suponha que você precise mandar 1.000 USDT para outra corretora. A origem oferece saque em ERC20 com taxa ilustrativa de 4 USDT, em TRC20 com 1 USDT e em Solana com 0,5 USDT. A corretora de destino só aceita depósito de USDT em ERC20 e TRC20. A opção mais barata que funciona é TRC20: chegam 999 USDT. Se você escolhesse Solana para economizar 0,5 USDT, o depósito poderia não ser creditado.","mistakes":["Escolher a rede pela menor taxa sem verificar se o destino aceita essa rede para aquele ativo.","Achar que, porque o endereço 0x é igual em duas redes EVM, tanto faz por qual rede enviar.","Confundir a versão de um token em uma rede com a versão em outra, como um token bridged com o nativo."],"faq":[{"q":"O que fazer se mandei pela rede errada?","a":"Abra um chamado no suporte do destino com o hash da transação. Algumas corretoras recuperam depósitos em redes não suportadas mediante taxa e prazo, mas isso não é garantido."},{"q":"ERC20 e TRC20 são moedas diferentes?","a":"Não, são padrões de token em redes diferentes: ERC20 no Ethereum e TRC20 na Tron. O USDT nas duas é emitido pela Tether, mas cada versão só circula na própria rede."}],"title":"Qual rede escolher para depositar cripto? Entenda","description":"Entenda o que é a rede de depósito, como escolher entre ERC20, TRC20 e outras e como evitar perder um envio pela rede errada.","related":[["wallet-address","Endereço de carteira (wallet address)","Um endereço de carteira é o identificador público, como 0x… no Ethereum ou bc1… no Bitcoin, que você informa para receber criptomoedas em uma rede específica."],["memo-tag","Memo / tag de destino","Memo ou tag de destino é um código extra, exigido em redes como XRP, Stellar, TON e algumas outras, que identifica a conta do destinatário quando vários clientes de uma corretora compartilham o mesmo endereço."],["gas-fee","Taxa de gás (gas fee)","Taxa de gás é o valor pago na moeda nativa de uma blockchain, como ETH no Ethereum, para que uma transação ou operação com contrato inteligente seja processada pela rede."],["withdrawal-fee","Taxa de saque","Taxa de saque é o valor cobrado por uma corretora quando você retira criptoativos para outro endereço ou retira reais para sua conta bancária, normalmente um valor fixo em cada moeda e rede."],["transaction-hash","Hash da transação (TxID)","O hash da transação (TxID) é o código único que identifica uma transação na blockchain e permite consultá-la em um explorador de blocos para ver valor, endereços, rede e confirmações."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Antes de transferir: não chute nenhum destes pontos"},"coin":null,"tool":null,"cta":false},"mempool":{"slug":"mempool","cat":"onchain","en":"Mempool","contentLocale":"pt-BR","term":"Mempool","aka":["mempool","memory pool","fila de transações"],"short":"Mempool é a área de espera onde as transações enviadas, mas ainda não confirmadas, ficam guardadas pelos nós da rede até serem incluídas em um bloco por um minerador ou validador.","body":[["Quando você envia ",["bitcoin","bitcoin"],", a transação é transmitida aos nós, que a verificam e a colocam na mempool. Cada nó tem a sua própria mempool, então o conteúdo pode variar um pouco entre eles. Os mineradores escolhem quais transações entram no próximo bloco e, como o espaço é limitado, priorizam as que pagam taxa maior por unidade de tamanho (sat/vB no Bitcoin)."],"Se a mempool está cheia, as taxas sobem e transações com taxa baixa podem ficar horas ou dias esperando. Algumas são descartadas depois de um tempo. No Bitcoin existem recursos como RBF (substituir a transação por outra com taxa maior) e CPFP (gastar a saída com uma taxa alta para puxar a anterior).",["Em redes como ",["Ethereum","ethereum"],", a mempool também é onde bots observam transações pendentes para tentar ganhar com ",["MEV","mev"],", por exemplo passando na frente de uma troca grande. Por isso algumas carteiras oferecem envio por canais privados."]],"example":"Suponha que você envie uma transação de 140 vB pagando 5 sat/vB, ou 700 satoshis de taxa, num momento em que a mempool exige cerca de 30 sat/vB para entrar no próximo bloco. Ela fica parada. Com RBF, você reenvia pagando 32 sat/vB, ou 4.480 satoshis, e ela tende a ser confirmada nos blocos seguintes.","mistakes":["Enviar com taxa mínima em horário de congestionamento e achar que a moeda sumiu.","Reenviar o mesmo pagamento de novo, sem RBF, e acabar pagando duas vezes quando as duas confirmam.","Pensar que a corretora pode acelerar uma transação que ainda está na mempool depois de enviada."],"faq":[{"q":"Por que minha transação está parada na mempool?","a":"Geralmente porque a taxa paga está abaixo do que os mineradores aceitam no momento. Você pode esperar, usar RBF se a carteira permitir ou CPFP a partir do recebedor."},{"q":"Uma transação pode sair da mempool sem confirmar?","a":"Sim. Nós podem descartar transações antigas ou com taxa muito baixa. Nesse caso os fundos continuam no endereço de origem e você pode reenviar."}],"title":"O que é mempool? Por que sua transação está pendente","description":"Entenda o que é a mempool, como as taxas definem a fila de confirmação e o que fazer com uma transação travada.","related":[["gas-fee","Taxa de gás (gas fee)","Taxa de gás é o valor pago na moeda nativa de uma blockchain, como ETH no Ethereum, para que uma transação ou operação com contrato inteligente seja processada pela rede."],["transaction-hash","Hash da transação (TxID)","O hash da transação (TxID) é o código único que identifica uma transação na blockchain e permite consultá-la em um explorador de blocos para ver valor, endereços, rede e confirmações."],["mev","MEV (valor máximo extraível)","MEV (valor máximo extraível) é o lucro que quem organiza as transações de um bloco, ou bots que pagam por prioridade, consegue obter escolhendo a ordem, incluindo ou excluindo transações."],["block-confirmations","Confirmações de bloco","Confirmações de bloco são a quantidade de blocos adicionados à blockchain a partir do bloco que incluiu sua transação, e indicam o quanto ela está consolidada e difícil de reverter."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Diz enviado, mas nunca chegou. Onde você deve olhar?"},"coin":null,"tool":null,"cta":false},"no-kyc-exchange":{"slug":"no-kyc-exchange","cat":"regulation","en":"No-KYC exchange","contentLocale":"pt-BR","term":"Corretora sem KYC","aka":["corretora sem KYC","exchange sem KYC","no-KYC exchange","corretora sem verificação"],"short":"Uma corretora sem KYC é uma plataforma que permite negociar ou sacar criptoativos sem verificação de identidade, total ou até certo limite, em geral com restrições de produtos e de valores.","body":[["Há dois grupos. As corretoras descentralizadas (",["DEX","dex"],"), como Uniswap ou Hyperliquid, funcionam por contratos inteligentes e você usa a própria carteira, sem cadastro. Já as corretoras centralizadas que oferecem uso sem ",["KYC","kyc"]," costumam permitir saques pequenos por dia e cobrar verificação a partir de certo valor ou quando algum alerta é acionado."],["A vantagem é privacidade e acesso rápido. As desvantagens são relevantes: muitas dessas plataformas não têm registro em nenhum regulador, o que deixa o cliente sem ",["proteção","hedging"]," em caso de bloqueio ou insolvência; a política pode mudar de repente e exigir KYC para liberar saques; e alguns países proíbem o acesso a plataformas não autorizadas."],"Antes de depositar, confira o limite de saque sem verificação, a reputação da plataforma, as taxas de saque e se ela atende sua região. Numa DEX, os riscos passam a ser contratos inteligentes, golpes de token e a segurança da sua própria carteira."],"example":["Suponha que uma plataforma permita sacar até o equivalente a 2 ",["BTC","bitcoin"]," por dia sem KYC. Você deposita 3 BTC e no dia seguinte tenta sacar tudo. Os primeiros 2 BTC saem, mas o restante só pode sair no dia seguinte ou após verificação. Se nesse meio tempo a plataforma mudar as regras, até o saldo de 1 BTC pode ficar preso esperando KYC."],"mistakes":["Depositar valores altos confiando que nunca será pedida verificação.","Achar que sem KYC significa sem rastreio, quando a blockchain é pública.","Não conferir se a plataforma bloqueia usuários do seu país nos termos de uso."],"faq":[{"q":"Existe corretora sem KYC legalizada?","a":"DEXs não exigem cadastro por natureza. Corretoras centralizadas reguladas, em geral, são obrigadas a fazer KYC, então as que dispensam costumam operar sem registro nas principais jurisdições."},{"q":"Uma corretora sem KYC pode pedir verificação depois?","a":"Sim. Muitas exigem KYC a partir de certo valor, ao detectar um alerta ou após mudança de política, e podem segurar saques até a verificação."}],"title":"O que é corretora sem KYC? Vantagens e riscos","description":"Veja o que é uma corretora sem KYC, a diferença entre DEX e plataformas centralizadas e quais limites e riscos existem.","related":[["kyc","KYC (conheça seu cliente)","KYC, sigla de know your customer (conheça seu cliente), é o processo em que uma corretora ou instituição financeira confirma a identidade do usuário com documento, selfie e dados pessoais antes de liberar serviços."],["dex","Corretora descentralizada (DEX)","Uma corretora descentralizada (DEX) é uma plataforma onde você troca criptomoedas diretamente da sua carteira por meio de contratos inteligentes, sem entregar a custódia a uma empresa."],["withdrawal-fee","Taxa de saque","Taxa de saque é o valor cobrado por uma corretora quando você retira criptoativos para outro endereço ou retira reais para sua conta bancária, normalmente um valor fixo em cada moeda e rede."],["centralized-exchange","Corretora centralizada (CEX)","Corretora centralizada (CEX) é uma empresa que intermedeia a compra e venda de criptomoedas, guarda os ativos dos clientes e opera seu próprio livro de ofertas, como Binance, OKX, Bybit ou Mercado Bitcoin."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"Como funciona o KYC e para quem você deve entregar seu documento?"},"coin":null,"tool":"/topics/no-kyc","cta":false},"fiat-on-ramp":{"slug":"fiat-on-ramp","cat":"regulation","en":"Fiat on-ramp","contentLocale":"pt-BR","term":"Rampa de entrada fiat (on-ramp)","aka":["on-ramp","rampa de entrada","fiat on-ramp","entrada em reais"],"short":"Uma rampa de entrada fiat (on-ramp) é qualquer forma de trocar dinheiro tradicional, como reais, por criptoativos, por exemplo depósito via Pix numa corretora, compra com cartão ou negociação P2P.","body":[["No Brasil, o caminho mais comum é depositar reais via Pix numa corretora com ",["KYC","kyc"]," e comprar ",["USDT","usdt"]," ou ",["BTC","bitcoin"]," no ",["mercado à vista","spot-trading"]," ou pela função de conversão. Outras opções são compra com cartão de crédito ou débito, geralmente mais cara, provedores integrados em carteiras e o ",["mercado P2P","p2p-trading"],", onde você paga diretamente outra pessoa."],["Cada rota tem custos diferentes: taxa de depósito, ",["spread","bid-ask-spread"]," embutido na cotação, taxa da ordem e, depois, taxa de saque se você levar a cripto para outra carteira. Comparar o valor final recebido em cripto é mais útil do que olhar só a taxa anunciada."],"O caminho inverso, de cripto para reais, é chamado de off-ramp. Antes de escolher, confira se a plataforma aceita depósitos no seu nome, se o Pix precisa sair de conta da mesma titularidade e quais são os limites do seu nível de verificação."],"example":"Suponha que você queira transformar 1.000 reais em USDT. Pela rota A, deposita via Pix sem taxa e compra no livro de ofertas a 5,50 reais com taxa de 0,1%, recebendo cerca de 181,6 USDT. Pela rota B, compra com cartão a 5,70 reais com taxa de 3%, recebendo cerca de 170,2 USDT. A diferença é de mais de 11 USDT no mesmo valor.","mistakes":["Comparar só a taxa anunciada e ignorar o spread embutido na cotação.","Fazer Pix de uma conta em nome de outra pessoa e ter o depósito devolvido ou bloqueado.","Comprar com cartão de crédito sem notar que o banco pode cobrar a operação como saque ou com encargos extras."],"faq":[{"q":"Qual a forma mais barata de comprar cripto no Brasil?","a":"Em geral, depositar reais via Pix numa corretora e comprar com ordem limitada no livro de ofertas sai mais barato do que cartão. Compare o valor final em cripto entre as opções."},{"q":"O que é off-ramp?","a":"É o caminho contrário: vender cripto e receber dinheiro tradicional, por exemplo sacando reais via Pix para sua conta bancária."}],"title":"O que é on-ramp? Como trocar reais por cripto","description":"Saiba o que é uma rampa de entrada fiat, como comparar Pix, cartão e P2P e quanto cada rota custa de verdade.","related":[["p2p-trading","P2P (negociação entre pessoas)","P2P é a negociação de cripto diretamente entre usuários, em que um compra e outro vende, geralmente USDT, combinando pagamento em reais por Pix ou transferência, com a corretora segurando a cripto em garantia até a confirmação."],["kyc","KYC (conheça seu cliente)","KYC, sigla de know your customer (conheça seu cliente), é o processo em que uma corretora ou instituição financeira confirma a identidade do usuário com documento, selfie e dados pessoais antes de liberar serviços."],["centralized-exchange","Corretora centralizada (CEX)","Corretora centralizada (CEX) é uma empresa que intermedeia a compra e venda de criptomoedas, guarda os ativos dos clientes e opera seu próprio livro de ofertas, como Binance, OKX, Bybit ou Mercado Bitcoin."],["stablecoin","Stablecoin (moeda estável)","Uma stablecoin é uma criptomoeda projetada para manter um valor estável, geralmente 1 dólar americano, por meio de reservas em moeda tradicional, garantia em cripto ou mecanismos de mercado."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"Primeiro depósito: de onde vem e para onde vai o dinheiro?"},"coin":null,"tool":null,"cta":true}});
